begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not (select rolcanlogin or rolbypassrls from pg_roles where rolname='carrier_security'),'Account function owner cannot login or bypass RLS');
select ok(not pg_has_role('authenticated','carrier_security','MEMBER'),'Client role cannot assume privileged function owner');
select ok(not has_schema_privilege('anon','private','USAGE'),'Anonymous cannot access private helpers');
select ok(not has_function_privilege('authenticated','private.auth_identity(uuid)','EXECUTE'),'Auth identity lookup is not a client RPC');
select ok(not has_function_privilege('authenticated','private.auth_session_valid(uuid,uuid)','EXECUTE'),'Raw Auth session lookup is closed');
select ok(not has_function_privilege('authenticated','private.revoke_sessions(uuid)','EXECUTE'),'Raw session deletion is closed');
select ok(not has_function_privilege('authenticated','public.register_staff(jsonb,uuid,text,text,text,uuid[])','EXECUTE'),'Account registration is server-only');
select ok(not has_function_privilege('authenticated','public.begin_staff_password(jsonb,uuid,integer,boolean)','EXECUTE'),'Password preparation is server-only');
select ok(not has_function_privilege('authenticated','public.finish_staff_password(uuid)','EXECUTE'),'Password finalization is server-only');
select ok(not has_function_privilege('authenticated','public.recover_staff_password(uuid,integer,uuid)','EXECUTE'),'Recovery is trusted-tool only');
select ok(not has_function_privilege('anon','public.admin_manage_staff(uuid,integer,text,text,boolean,uuid[])','EXECUTE'),'Anonymous admin mutation denied');
select ok(not has_function_privilege('authenticated','public.staff_access_token_hook(jsonb)','EXECUTE'),'Clients cannot mint token-hook claims');
select ok(has_function_privilege('supabase_auth_admin','public.staff_access_token_hook(jsonb)','EXECUTE'),'Auth alone can invoke the token hook');
select ok(not (select public from storage.buckets where id='receipts'),'Evidence bucket is private');
select ok(not has_table_privilege('authenticated','public.staff_profiles','UPDATE'),'No direct role/status/password-flag writes');
select ok(not has_table_privilege('authenticated','public.staff_offices','INSERT'),'No direct assignment writes');
select ok(not has_table_privilege('authenticated','public.trips','UPDATE'),'Trip commands must use backend authorization');
select ok(not has_table_privilege('authenticated','public.financial_events','INSERT,UPDATE,DELETE'),'Financial events have no direct client writes');
select ok(not has_table_privilege('authenticated','public.journal_lines','INSERT,UPDATE,DELETE'),'Journal has no direct client writes');
select ok(not has_table_privilege('authenticated','public.allocations','INSERT,UPDATE,DELETE'),'Allocations have no direct client writes');
select ok(not has_table_privilege('authenticated','public.idempotency_records','INSERT,UPDATE,DELETE'),'Idempotency results have no direct client writes');
select ok(not has_table_privilege('authenticated','public.financial_events','SELECT'),'Unscoped event metadata stays closed');
select set_config('request.jwt.claims','{}',true);
set local role authenticated;
select is((select count(*)::integer from public.trips),0,'No verified live session sees no trips, including direct queries');
select throws_ok('select public.get_session_profile()','42501','FORBIDDEN','Missing session denies profile RPC');
select throws_ok('select public.list_staff_accounts()','42501','FORBIDDEN','Missing session denies account list RPC');
select throws_ok($$select public.get_balance_summary('ALL')$$,'42501','FORBIDDEN','Missing session denies complete balances');
reset role;
select * from finish();
rollback;
